<?php require __DIR__.'/app/bootstrap.php'; csrf_check(); if(isset($_POST['add'])){$id=(int)($_POST['product_id']??0);$qty=max(1,(int)($_POST['quantity']??1));$s=db()->prepare("SELECT stock FROM products WHERE id=? AND status='active'");$s->execute([$id]);$stock=$s->fetchColumn();if($stock!==false && $stock>0)$_SESSION['cart'][$id]=min((int)$stock,($_SESSION['cart'][$id]??0)+$qty);header('Location: '.url('cart.php'));exit;}if(isset($_POST['update'])){foreach(($_POST['qty']??[]) as $id=>$qty){$id=(int)$id;$qty=(int)$qty;if($qty<1)unset($_SESSION['cart'][$id]);else $_SESSION['cart'][$id]=$qty;}header('Location: '.url('cart.php'));exit;}if(isset($_GET['remove'])){unset($_SESSION['cart'][(int)$_GET['remove']]);header('Location: '.url('cart.php'));exit;}$items=[];$total=0;if(!empty($_SESSION['cart'])){$ids=array_keys($_SESSION['cart']);$marks=implode(',',array_fill(0,count($ids),'?'));$s=db()->prepare("SELECT * FROM products WHERE id IN ($marks)");$s->execute($ids);$items=$s->fetchAll();foreach($items as &$it){$it['qty']=$_SESSION['cart'][$it['id']];$total+=$it['qty']*$it['price'];}unset($it);}$pageTitle='Quick Cart — NEXT TECH';require __DIR__.'/includes/header.php'; ?><section class="page-intro"><span class="eyebrow">YOUR SELECTION</span><h1>Quick Cart</h1></section><?php if($items): ?><form method="post" class="cart-list"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><?php foreach($items as $it): ?><div class="cart-row"><div><strong><?=e($it['name'])?></strong><small><?=money($it['price'])?> each</small></div><input class="qty-input" type="number" min="0" name="qty[<?=(int)$it['id']?>]" value="<?=(int)$it['qty']?>"><b><?=money($it['price']*$it['qty'])?></b><a href="<?=e(url('cart.php?remove='.(int)$it['id']))?>">Remove</a></div><?php endforeach; ?><div class="cart-total">Subtotal <strong><?=money($total)?></strong></div><button class="btn btn-primary" name="update" value="1">Update Cart</button><p class="notice">Online checkout and payment will be connected in a later phase.</p></form><?php else: ?><p class="empty-state">Your cart is empty.</p><?php endif; ?><?php require __DIR__.'/includes/footer.php'; ?>
